#include <stdio.h>

#define INF 1000000000

int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int adj[105][105];
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            adj[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d %d %d", &u, &v, &c);
        if (c < adj[u][v]) {
            adj[u][v] = c;
            adj[v][u] = c;
        }
    }

    int dist[105];
    int visited[105] = {0};

    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
    }
    dist[1] = 0;

    for (int i = 1; i <= n; i++) {
        int u = -1;
        for (int j = 1; j <= n; j++) {
            if (!visited[j] && (u == -1 || dist[j] < dist[u])) {
                u = j;
            }
        }

        if (dist[u] == INF) break;
        visited[u] = 1;

        for (int v = 1; v <= n; v++) {
            if (adj[u][v] != INF && dist[u] + adj[u][v] < dist[v]) {
                dist[v] = dist[u] + adj[u][v];
            }
        }
    }

    printf("%d\n", dist[n]);

    return 0;
}
